CREATE TABLE agent_conversations(id uuid PRIMARY KEY,profile_id uuid NOT NULL REFERENCES agent_profiles(id),project_id uuid NOT NULL REFERENCES projects(id),environment_id uuid NOT NULL REFERENCES environments(id),profile_revision integer NOT NULL,profile_hash text NOT NULL,title text NOT NULL CHECK(length(title)<=120),revision integer NOT NULL,cursor integer NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE agent_chat_turns(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES agent_conversations(id),sequence integer NOT NULL,task_id uuid NOT NULL REFERENCES agent_tasks(id),partial_text text NOT NULL CHECK(octet_length(partial_text)<=32768),vendor_sequence bigint NOT NULL,history jsonb NOT NULL,omitted_turns integer NOT NULL,CONSTRAINT agent_chat_turn_sequence UNIQUE(conversation_id,sequence),CONSTRAINT agent_chat_turn_task UNIQUE(task_id));
CREATE TABLE agent_chat_events(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES agent_conversations(id),cursor integer NOT NULL,turn_id uuid REFERENCES agent_chat_turns(id),type text NOT NULL,text text CHECK(octet_length(text)<=4096),state text,occurred_at timestamptz NOT NULL,CONSTRAINT agent_chat_event_cursor UNIQUE(conversation_id,cursor));
CREATE TABLE agent_chat_artifacts(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES agent_conversations(id),task_id uuid NOT NULL REFERENCES agent_tasks(id),data jsonb NOT NULL);
CREATE TABLE agent_chat_proposals(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES agent_conversations(id),task_id uuid NOT NULL REFERENCES agent_tasks(id),data jsonb NOT NULL);
